-- =============================================================================
-- Akademi kaynak sicili seed V1 — ADAY kayıtlar (status=candidate).
-- =============================================================================
-- docs/academy/sources_candidates.json'dan üretildi
-- (scripts/academy_probe_sources.ps1 canlı erişim raporu:
-- docs/academy/source_verification.json). ADAY = erişim/lisans onayı DEĞİL;
-- worker gerçek içerik çıkarımını kanıtlayınca status=active yapılır
-- (service_role). Idempotent: on conflict (slug) do nothing.

-- Bot–kaynak eşleştirme: kaynak konuları → bot anahtarı (idempotent).
select t.topic, s.id, 100
from public.academy_sources s
cross join lateral unnest(s.topics) as t(topic)
join public.academy_bot_profiles b on b.bot_key = t.topic
on conflict (bot_key, source_id) do nothing;
